#include <stdio.h>
#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

int main(void) {
    size_t count = 3;          /* sizes, counts, array indexes. */
    int32_t balance = -250;    /* exactly 32 bits when that's required. */
    double price = 19.99;      /* measurements, fractions. */
    bool paid = false;         /* true or false. */
    char grade = 'A';          /* one character (a small integer). */

    printf("int: %zu bytes, long: %zu bytes\n", sizeof(int), sizeof(long));
    return 0;
}
```

| Need | Type |
|---|---|
| size or count of objects. | `size_t`. |
| exact width (file formats, protocols). | `int32_t`, `uint8_t`... |
| ordinary whole numbers. | `int`. |
| fractional measurements. | `double`. |
| yes/no flag. | `bool`. |

